import { test, expect } from '@playwright/test';

// Resolve :param routes to a real resource id (v129: literal ':id' nav → bad UUID → empty page).
const __API_BASE = process.env.API_URL || 'http://localhost:3000/api';
const __RESOLVE_OVERRIDES = {};
async function resolveRoute(page, route) {
  if (!/\/:[A-Za-z_]/.test(route)) return route;
  const segs = route.split('/').filter(Boolean);
  const idIdx = segs.findIndex(function (s) { return s.charAt(0) === ':'; });
  let listSegs = segs.slice(0, idIdx);
  if (['admin', 'worker', 'company', 'staff', 'operator'].indexOf(listSegs[0]) >= 0) listSegs = listSegs.slice(1);
  const listPath = '/' + listSegs.join('/');
  // v148: the resource LIST endpoint isn't always /<resource>. It can be
  //   /<resource>/nearby (geo list, e.g. instructors), /my/<resource> (owned,
  //   e.g. bookings), or /<resource>/me. The old code only tried /<resource>;
  //   when that 404s it fell back to 'unknown' → /<resource>/unknown → detail
  //   404s → the page errors → FALSE failure even though the page is fine.
  //   Try several candidates and use the first that yields a real id.
  const __ovr = (__RESOLVE_OVERRIDES && __RESOLVE_OVERRIDES[listPath]) ? [].concat(__RESOLVE_OVERRIDES[listPath]) : [];
  const __cands = __ovr.concat([listPath, listPath + '/nearby?lat=37.5&lng=127&radiusKm=30', '/my' + listPath, listPath + '/me']);
  let id = '';
  for (const __lp of __cands) {
    try {
      const r = await page.request.get(__API_BASE + __lp);
      if (!r.ok()) continue;
      const j = await r.json().catch(function () { return null; });
      const items = (j && j.data && (j.data.items || j.data)) || (j && j.items) || [];
      if (Array.isArray(items) && items[0] && typeof items[0] === 'object') {
        // v147: list items don't always key the PK as `id` — chat rooms use
        // `roomId`, some use `<resource>Id`. Take `id`, else the first own
        // field whose name ends in `id`/`Id` (skipping foreign keys like
        // `bookingId` only if a primary `*roomId/*Id` named after the route
        // exists — but first own id-field is a safe, general default).
        const __row = items[0];
        let __id = __row.id;
        if (__id === undefined || __id === null) {
          const __idKey = Object.keys(__row).find(function (k) { return /(^|[a-z])id$/i.test(k) && (typeof __row[k] === 'string' || typeof __row[k] === 'number'); });
          if (__idKey) __id = __row[__idKey];
        }
        if (__id !== undefined && __id !== null) { id = String(__id); break; }
      }
    } catch (e) { /* try next candidate */ }
  }
  return route.replace(/:[A-Za-z_]+/g, id || 'unknown');
}

async function __vis(loc) { try { return await loc.isVisible(); } catch { return false; } }
async function __txt(loc) { try { return (await loc.textContent()) || ''; } catch { return ''; } }

async function gotoStory(page, route, primary) {
  const resp = await page.goto(route);
  const nf = await __vis(page.locator('[data-testid*="not-found" i], [data-testid*="notfound" i]').first());
  if (nf && primary && primary !== route) { return await page.goto(primary); }
  return resp;
}

